 public static void Run(string input,string output){Directory.CreateDirectory(output);int checks=0;void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}var p=SongProject.Load(input);var rig=Rig.Load(p.Skeleton);var dance=MotionClip.Load(p.Dance.Path,p.Dance.HkxBindingIndex,p.Dance.IdentityRigProof);var camera=MotionClip.Load(p.Camera.Path,p.Camera.HkxBindingIndex,p.Camera.IdentityRigProof);var audio=AudioImport.Load(p.Audio.Path);p.CameraBone=97;p.ExportIn=30;p.ExportOut=31.03;var packages=new List<string>();
  foreach(var kind in new[]{"both","dance","camera"}){p.Id="same-project";p.Title="Same title";string folder=GameExporter.Export(output,p,kind=="camera"?null:dance,kind=="dance"?null:camera,audio,rig);packages.Add(folder);using var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(folder,"song.json")));var j=doc.RootElement;Check(j.GetProperty("schemaVersion").GetInt32()==4,"new runtime schema");Check(j.TryGetProperty("dance",out _)==(kind!="camera"),"optional dance metadata");Check(j.TryGetProperty("cameraSamples",out _)==(kind!="dance"),"optional camera metadata");Check(File.Exists(Path.Combine(folder,"config.json"))==(kind!="camera"),"OAR only for dance");Check(!Directory.GetFiles(folder,"*",SearchOption.AllDirectories).Any(x=>x.EndsWith(".danceproj")||x.EndsWith(".txt")||x.EndsWith(".md")||x.Contains("Diagnostics")),"runtime files only");foreach(var h in j.GetProperty("hashes").EnumerateObject()){Check(Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(Path.Combine(folder,h.Name))))==h.Value.GetString(),"runtime asset hash");}Check(Math.Abs(WaveAudio.Load(Path.Combine(folder,"music.wav")).Duration-1.03)<1.0/audio.SampleRate,"audio master duration");}
  foreach(var folder in packages){using var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(folder,"song.json")));var j=doc.RootElement;if(!j.TryGetProperty("dance",out var d)){Check(!Directory.Exists(Path.Combine(folder,"male")),"camera-only has no male animation");continue;}Check(d.GetString()=="female/mt_idle.hkx"&&!File.Exists(Path.Combine(folder,"mt_idle.hkx"))&&!j.GetProperty("hashes").TryGetProperty("mt_idle.hkx",out _),"root dance is neither produced nor hashed");var expected=SHA256.HashData(File.ReadAllBytes(Path.Combine(folder,d.GetString()!)));foreach(var route in new[]{"danceFemale","danceMale"})Check(expected.SequenceEqual(SHA256.HashData(File.ReadAllBytes(Path.Combine(folder,j.GetProperty(route).GetString()!)))),"same motion for both graph routes");var conditions=File.ReadAllText(Path.Combine(folder,"config.json"));Check(!conditions.Contains("IsFemale")&&!conditions.Contains("IsMale"),"no sex condition");}
  string legacy=Path.Combine(output,".legacy-validation");Directory.CreateDirectory(legacy);foreach(var file in Directory.EnumerateFiles(packages[0],"*",SearchOption.AllDirectories)){string target=Path.Combine(legacy,Path.GetRelativePath(packages[0],file));Directory.CreateDirectory(Path.GetDirectoryName(target)!);File.Copy(file,target,true);}var legacyJson=System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(Path.Combine(legacy,"song.json")))!;legacyJson["dance"]="mt_idle.hkx";legacyJson["hashes"]!["mt_idle.hkx"]=new string('0',64);File.WriteAllText(Path.Combine(legacy,"song.json"),legacyJson.ToJsonString());PackageUpdates.Validate(legacy);Check(!File.Exists(Path.Combine(legacy,"mt_idle.hkx")),"legacy root reference and obsolete hash ignored without root file");legacyJson["hashes"]!["female/mt_idle.hkx"]=new string('0',64);File.WriteAllText(Path.Combine(legacy,"song.json"),legacyJson.ToJsonString());bool badRoute=false;try{PackageUpdates.Validate(legacy);}catch(InvalidDataException){badRoute=true;}Check(badRoute,"female route hash is still enforced");
  p.PackageIds["camera"]="camera-short";p.ExportOut=30.5;packages.Add(GameExporter.Export(output,p,null,camera,audio,rig));p.ExportOut=31.03;
  string id=p.PackageId(true,false);string repeat=GameExporter.Export(output,p,dance,null,audio,rig);using(var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(repeat,"song.json"))))Check(doc.RootElement.GetProperty("id").GetString()==id,"reexport retains package ID");
  string independent=GameExporter.Export(output,p,dance,null,audio,rig,true);using(var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(independent,"song.json"))))Check(doc.RootElement.GetProperty("id").GetString()!=id,"new independent package ID");
