  var app=Application.Current??new Application();var track=new TrackEdit{Path="test.hkx",In=2,Out=22,Start=10,Speed=2};var timeline=new TimelineView{Project=new SongProject{Dance=track,ExportOut=60},Span=60,Playhead=5};timeline.Measure(new Size(1200,246));timeline.Arrange(new Rect(0,0,1200,246));
