  body=Body(0);double savedStart=track.Start;timeline.PointerDown(body);timeline.PointerMove(new Point(body.X+X(2)-X(0),body.Y),true);timeline.CancelDrag();Check(track.Start==savedStart&&track.In==before.input&&track.Out==before.output,"cancel explicitly rolls body drag back");Check(edits==1,"cancel does not commit an edit");
  body=Body(0);timeline.PointerDown(body);Check(timeline.DragEdge==0,"bound check uses body");timeline.PointerMove(new Point(-100,body.Y),true);timeline.CommitDrag();Check(track.Start>=0&&track.In==2&&track.Out==22&&track.Speed==2,"left body drag bound retains source range");
  timeline.PointerDown(timeline.RulerPoint(20));timeline.PointerMove(timeline.RulerPoint(30),true);timeline.CommitDrag();Check(Near(sought,30),"header/playhead continuous scrub");
  timeline.PointerDown(timeline.AtTimeInRow(30,1));timeline.PointerMove(timeline.AtTimeInRow(35,1),true);timeline.CommitDrag();Check(Near(sought,35),"playhead drag over tracks");
  timeline.Project=new SongProject{Dance=track,ExportOut=60};track.In=2;track.Out=22;track.Start=10;timeline.Playhead=50;
  var clip=timeline.ClipBounds(0);timeline.PointerDown(new Point(clip.Left+2,clip.Top+clip.Height/2));Check(timeline.DragEdge==-1,"left handle selected independently from body");timeline.PointerMove(new Point(clip.Left+2+X(1)-X(0),clip.Top+clip.Height/2),true);timeline.CommitDrag();Check(track.In==4&&track.Out==22&&track.Start==11&&track.Speed==2&&Near(track.TimelineEnd,20),"left edge trimming retains source mapping and fixed right edge");
  timeline.SourceDurations=[30,0,0];clip=timeline.ClipBounds(0);timeline.PointerDown(new Point(clip.Right-2,clip.Top+clip.Height/2));Check(timeline.DragEdge==1,"right handle selected independently from body");timeline.PointerMove(new Point(clip.Right-2+X(2)-X(0),clip.Top+clip.Height/2),true);timeline.CommitDrag();Check(track.Out==26&&track.In==4&&track.Start==11&&track.Speed==2,"right edge trimming remains operational");
  var removal=new SongProject{Dance=new(){Path="dance.hkx",Out=20},Camera=new(){Path="camera.hkx",Out=20},Audio=new(){Path="music.wav",Out=20}};timeline.Project=removal;timeline.Playhead=50;timeline.RemoveTrack=i=>removal.RemoveTrack(i);
  Check(timeline.TrackMenu(timeline.AtTimeInRow(25,0))==null&&timeline.TrackMenu(new Point(X(5),timeline.ClipBounds(0).Top-1))==null,"empty right click has no menu");
  for(int i=0;i<3;i++){double seekBefore=sought;var menu=timeline.TrackMenu(timeline.AtTimeInRow(5,i));Check(menu!=null,"actual track context menu");var item=(System.Windows.Controls.MenuItem)menu!.Items[0];Check((string)item.Header==UiText.T("t0337"),"context label");item.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.MenuItem.ClickEvent));Check(new[]{removal.Dance,removal.Camera,removal.Audio}[i].Path==""&&seekBefore==sought,"context delete only target without seek");Check(timeline.TrackMenu(timeline.AtTimeInRow(5,i))==null,"removed track no context");}
  string empty=Path.Combine(output,"empty.danceproj");removal.Save(empty);var emptyLoaded=SongProject.Load(empty);Check(new[]{emptyLoaded.Dance,emptyLoaded.Camera,emptyLoaded.Audio}.All(x=>x.Path==""),"empty tracks save roundtrip");
  for(int row=0;row<3;row++){var target=timeline.DropLocation(timeline.AtTimeInRow(15,row));Check(target.Row==row&&Near(target.Time,15),"Explorer drop uses the actual lane and current timeline transform");}
  Check(timeline.DropLocation(new Point(0,0)).Row==-1&&timeline.DropLocation(new Point(-100,0)).Time==0,"ambiguous drop and negative-time bound");
